// Section 17D: Deterministic Date Maths for Schedule Variance (GD-I7)
const today = new Date();
const dayMs = 86400000;

// Sample stage plan parameters
const plannedStart = new Date('2026-09-01');
const plannedEnd = new Date('2026-10-15');
const reraPossession = new Date('2028-03-31');
const actualPercent = 62.0;
const blockersCount = 1;

const totalDays = Math.max(1, (plannedEnd - plannedStart) / dayMs);
const elapsedDays = Math.max(0, (today - plannedStart) / dayMs);
const plannedPct = Math.min(100, Math.max(0, (elapsedDays / totalDays) * 100));
const daysBehind = Math.max(0, Math.round(((plannedPct - actualPercent) / 100) * totalDays));

const threatensRera = (plannedEnd.getTime() + (daysBehind * dayMs)) > reraPossession.getTime();

let status = 'on_track';
if (daysBehind > 21 || threatensRera) {
  status = 'at_risk';
} else if (daysBehind > 7 || blockersCount >= 2) {
  status = 'watch';
}

return [{
  json: {
    project_id: 'PRJ-GH-KOKAPET',
    tower: 'Tower B',
    stage: '7th Floor Slab',
    planned_pct: Math.round(plannedPct),
    actual_pct: actualPercent,
    days_behind: daysBehind,
    status: status,
    site_update_received: true,
    stage_claimed_complete: actualPercent >= 100.0
  }
}];

// Section 17E: Per-Buyer Demand Math & Batch Total (GD-I3 & GD-I4)
const stage = '7th Floor Slab';
const demandPct = 15.0; // 15% slab stage
const sampleLedger = [
  { project_id: 'PRJ-GH-KOKAPET', unit_id: 'TB-1204', buyer_name: 'Ravi Kumar', phone: '+919876543210', agreement_value: 12502350, status: 'active', last_demanded_stage: '4th Floor Slab' },
  { project_id: 'PRJ-GH-KOKAPET', unit_id: 'TA-804', buyer_name: 'Anita Sharma', phone: '+919876543211', agreement_value: 12757500, status: 'active', last_demanded_stage: '4th Floor Slab' }
];

// GD-I4: Filter by active status, project, valid phone, key by unit_id
const validBuyers = sampleLedger.filter(r => 
  r.project_id === 'PRJ-GH-KOKAPET' &&
  r.status === 'active' &&
  r.phone &&
  r.last_demanded_stage !== stage
);

// GD-I3: Deterministic Code Node Arithmetic
const rows = validBuyers.map(r => ({
  unit_id: r.unit_id,
  buyer_name: r.buyer_name,
  phone: r.phone,
  agreement_value: r.agreement_value,
  amount_due: Math.round(r.agreement_value * (demandPct / 100.0))
}));

const totalDue = rows.reduce((acc, r) => acc + r.amount_due, 0);
const escrow70Amount = Math.round(totalDue * 0.70);

return [{
  json: {
    stage: stage,
    demand_percent: demandPct,
    buyers_count: rows.length,
    total_amount_due_inr: totalDue,
    escrow_70_amount_inr: escrow70Amount,
    rows: rows,
    photo_proof: 'https://cdn.skyline.in/evidence/slab7_pour_completed.jpg'
  }
}];

